set -euo pipefail
umask 077
test "$(hostname -s)" = k8s-control01
test "$(id -u)" = 0
TASK=$(mktemp -d /root/sec19-backup-precheck.XXXXXXXX)
printf 'TASK_DIR=%s
' "$TASK"
cd "$TASK"
base64 -d > source.tar <<'SOURCE_B64'

SOURCE_B64
echo '0c450334411cbf28ad62d90ee41298d9c5dd87be3ecd40a78ec5d93f566156e1  source.tar' | sha256sum -c -
tar -xf source.tar
CODE="$TASK/ops/p1-sec01-isolated-tests"
(cd "$CODE" && sha256sum -c SHA256SUMS) > bundle-verify.txt
printf 'SOURCE_HEAD=1b5470e8c9902e7561dbe56fa9129bcf45ba7bb3
' > source-head.txt
date -u +%FT%TZ > started-utc.txt
timeout 15 kubectl --kubeconfig=/etc/kubernetes/admin.conf --request-timeout=10s get nodes -o json > nodes-before.json 2> nodes-before.stderr
python3 "$CODE/checks.py" nodes < nodes-before.json > nodes-before-verdict.txt
set +e
KC='kubectl --kubeconfig=/etc/kubernetes/admin.conf --request-timeout=10s' bash "$CODE/backup.sh" precheck > precheck.stdout 2> precheck.stderr
rc=$?
set -e
printf '%s
' "$rc" > precheck.rc
timeout 15 kubectl --kubeconfig=/etc/kubernetes/admin.conf --request-timeout=10s get nodes -o json > nodes-after.json 2> nodes-after.stderr && python3 "$CODE/checks.py" nodes < nodes-after.json > nodes-after-verdict.txt
date -u +%FT%TZ > finished-utc.txt
cat precheck.stdout
cat precheck.stderr >&2
printf 'TASK_DIR=%s PRECHECK_RC=%s
' "$TASK" "$rc"
exit "$rc"
